"""Measured tables; interpret scientific/security limitations in the main report."""
import json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs/evaluation/vina_tasks_2026-09-10'
s=json.loads((OUT/'summary.json').read_text());rows=[json.loads(x) for x in (OUT/'campaign.jsonl').read_text().splitlines()]
lines=['# Distributed Vina measured results, 10 September 2026','','Generated by `scripts/write_vina_task_results.py`; all times below are measured, not projected. Three reused targets and four actives/four decoys per target form a diagnostic pilot. No independently replicated scientific or browser population claim.','','## Normal task aggregation','','Score-selected symmetry-aware RMSD in Å. Source starts from the prepared crystal input; converged uses the independent conformer. AUC uses eight ligands per target; uncertainty intervals are in `summary.json`. A dash denotes no evaluated configuration.','','| Target | Runs | Source RMSD | Independent RMSD | Ranking AUC |','|---|---:|---:|---:|---:|']
def num(x,precision=3):return '-' if x is None else f'{x:.{precision}f}'
for t in s['targets']:
 for c in t['configs']:
  if c['method']!='normal':continue
  red={r['conformer']:r['rmsd_A'] for r in c['redocking']};lines.append(f"| {t['target']} | {c['point']} | {num(red.get('source'))} | {num(red.get('converged'))} | {num(c['ranking']['auc'] if c['ranking'] else None)} |")
lines+=['','Downloaded stock E8 controls use the same prepared ligand subset. Missing runs are not silently dropped or assigned scores.','']
for t in s['targets']:lines.append(f"- {t['target']}: {t['stock_subset_successes']}/8 successful controls; complete AUC {num(t['stock_subset_quality']['auc'] if t['stock_subset_quality'] else None)}; worst/best bounds allowing missing scores {t['stock_subset_auc_bounds']}.")
lines+=['','## Many shorter runs versus one normal task','','Each cap is compared with the first normal task, not with E8. Evaluation-matched and closest-MC-time-matched arms are distinct; neither claims an exactly equal end-to-end cost.','','| Target | Matching | Cap | Source RMSD | Independent RMSD | AUC | Median ranking MC seconds |','|---|---|---:|---:|---:|---:|---:|']
for t in s['targets']:
 for c in t['configs']:
  if c['method']=='normal':continue
  red={r['conformer']:r['rmsd_A'] for r in c['redocking']};lines.append(f"| {t['target']} | {c['method']} | {c['point']} | {num(red.get('source'))} | {num(red.get('converged'))} | {num(c['ranking']['auc'] if c['ranking'] else None)} | {num(c['ranking_median_search_ms']/1000 if c['ranking_median_search_ms'] is not None else None)} |")
lines+=['','## Actual per-run native molecular cost','','Pooled across tasks in the defined pilot. These percentiles describe ligand/run heterogeneity, not repeated timing uncertainty. Initialization, serialization and finalization are excluded.','','| Task budget | Observed runs | Median seconds | Min seconds | Max seconds |','|---|---:|---:|---:|---:|']
for cap in [0,16000,64000,256000]:
 selected=[r for r in rows if r.get('cap')==cap and (r.get('method')=='matched' or r.get('method')=='normal' and r['runs']==(32 if r['id']=='crystal' else 8))];times=[m['ms']/1000 for r in selected for m in r['unit_metrics']]
 if times:lines.append(f'| {cap or "normal heuristic"} | {len(times)} | {statistics.median(times):.3f} | {min(times):.3f} | {max(times):.3f} |')
e=json.loads((OUT/'e32.json').read_text());eq=s['e32_score_selected_rmsd_A'];lines+=['','## E32 control: FA10 source crystal only','','| Configuration | Independent tasks | MC seconds | Score-selected RMSD Å |','|---|---:|---:|---:|',f"| Normal same-build E32 | 32 | {e['normal_search_ms']/1000:.3f} | {eq['normal_pose']:.3f} |",f"| 256k tasks, evaluation matched | {e['medium_runs']} | {e['medium_search_ms']/1000:.3f} | {eq['medium_pose']:.3f} |",f"| 256k tasks, closest MC time | {e['wallmatched_runs']} | {e['wallmatched_search_ms']/1000:.3f} | {eq['wallmatched_pose']:.3f} |",'',f"All 32 split raw pools/traces equal the same-build monolithic control: **{all(e['split_task_trace_exact'])}**. Final pose equality is asserted by the benchmark. Downloaded stock E32 RMSD: **{num(eq.get('downloaded_stock_pose'))} Å**. Its elapsed wall time is **{e['stock']['wall_ms']/1000:.3f} s**, including setup and finalization; do not equate that denominator with MC-only times."]
b=json.loads((OUT/'browser.json').read_text());lines+=['','## Real Chrome and same-WASM Node replay','','One source FA10 ligand, four runs per budget. No native/WASM bit-equivalence claim. Warm compute below excludes initialization/network/database; commitment timing is host Node, not browser.','','| Cap | Chrome MC seconds | Chrome calls seconds | Molecular fraction of calls | q | Replay + audit seconds | Calls / audit ratio |','|---|---:|---:|---:|---:|---:|---:|']
browser_notes=[]
for r in b['rows']:
 mc=sum(x['ms'] for x in r['runs']);calls=sum(x['call_ms'] for x in r['runs'])
 for check in r['checks']:lines.append(f"| {r['cap'] or 'normal'} | {mc/1000:.3f} | {calls/1000:.3f} | {100*mc/calls:.1f}% | {check['q']} | {check['total_ms']/1000:.3f} | {calls/check['total_ms']:.2f}× |")
 browser_notes+=['',f"Budget {r['cap'] or 'normal'}: science payload {r['science_bytes']:,} bytes for four runs; host commitment {r['commit_ms']:.3f} ms. One-run replay took {r['single_replay']['total_ms']/1000:.3f} s, compared with that Chrome run's {r['runs'][0]['call_ms']/1000:.3f} s.",'']
lines += browser_notes
lines += ['',f"Maximum observed client allocated WASM heap after measured calls: {max(x['heap_bytes'] for r in b['rows'] for x in r['runs']):,} bytes; not process peak RSS. Artifact/input delivery bytes (before compression/cache): {b['assets']}.",'']
lines += [f"Chrome version: {b['browser']}. Initial map computation: client {b['clientInit']['init_ms']/1000:.3f} s, server {b['serverInit']/1000:.3f} s. Client initialized WASM heap: {b['clientInit']['heap']:,} bytes (allocated heap, not process peak RSS).",'','## Durable integration','','The local ingestion test uses 32 actual 16k-cap task outputs, simulated visitors, per-session postcommit replay and an atomic SQLite ledger. It intentionally consumes previously computed useful work.','']
i=json.loads((OUT/'ingestion.json').read_text())
for r in i['results']:lines.append(f"- {r['sessions']} sessions × {r['runs_per_session']} runs, q={r['q_per_session']} per session: {r['replayed_runs']} actual replays, {r['replay_ms']/1000:.3f} s; protocol/storage {r['protocol_storage_ms']:.3f} ms. Ordered merged pose exact: {r['ordered_merge_exact']}; verified coverage {r['coverage']['replay_verified']}/32.")
lines+=['','Scientific outputs are provisional unless replayed; later verification can upgrade the exact stored digest. Duplicate completed units are rejected. This is local integration, not 32 real participants or distributed production concurrency.','']
(ROOT/'docs/research/VINA_TASK_MEASUREMENTS_2026-09-10.md').write_text('\n'.join(lines),encoding='utf8');print('Wrote measured tables')
